"""Record the exact standalone V17 artifact after all native checks pass."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[2];base=root/'output/elyndor/pixellab-v17'
def read(name):return json.loads((base/name).read_text(encoding='utf-8'))
a=json.loads((root/'output/elyndor/continuous-standalone-audit.json').read_text());reg=read('regression.json');revision=read('revision/report.json');pump=read('pump-fixed.json');campaign=read('campaign/report.json');performance=read('performance/native.json');combat=read('combat-profile-final.json');atlas=read('atlas-performance.json');voices=read('audio-audit.json');sounds=read('soundtrack-audit.json');lighting=read('lighting/report.json');water=read('water/report.json');journey=read('journey/report.json');macro=read('overworld/report.json')
sha=hashlib.sha256((root/'index.html').read_bytes()).hexdigest()
assert sha==reg['sha256']==a['sha256'] and a['sourceMatchesArtifact'] and not a['cropWarnings']
assert len(reg['checks'])==26 and all(q['pass']for q in reg['checks'])
assert all(q['pass']for q in [revision,atlas,voices,sounds,lighting,water,journey,macro])
assert campaign['campaign']['final']=='complete' and not campaign['errors'] and not campaign['voiceMissing']
assert pump['tick']['max']<50 and not pump['newPrograms'] and not pump['errors']
assert not combat['newPrograms'] and combat['cpu']['p95']<25
transcripts=json.loads((root/'elyndor/audio/transcription-audit-v17.json').read_text());assert transcripts['clips']==23 and not transcripts['unresolvedWordDifferences']
r={'release':'elyndor-2026-10-28-river-guidance-shared-overworld-v17','game':'The Last Light of Elyndor','artifact':{'file':'index.html','bytes':a['bytes'],'sha256':sha,'offline':True},
 'changes':['Bridge deck and graded approaches share the actual town paving material, texture scale and phase; a paved inn approach clears the entry garden','Exact terrain cuts under four town stairways remove coplanar surfaces without exposing triangular gaps; merged masonry faces are separated','Building cutaways require actual mesh occlusion inside the solid house and roof footprint; approaches, awnings and chimneys alone do not hide a building','Validated representative approach avoids the synchronous post-pump pathfinding search; steady water geometry stops uploading redundant vertex buffers','Directed action-based tutorial with 23 recorded world-narrator lessons, pulsing UI highlights, Open/Continue controls, replay, optional skip and projected interaction arrows','Persistent selected-enemy arrow, enemies and readable title/turn-order backplates at top left, party status at top right','Larger textured attack ribbons, impact rings, sparks, smoke, spell beams and pooled dynamic lighting','Depleted downstream channels progressively widen, rise and flow after gate repair; reservoir, cascade endpoints and reflection planes share the hydraulic state','Continuous non-pixel cloud density, opposite-side overhead key light, sky bounce, world-space rain puddles, wet surfaces and synchronized foliage/shadow wind gusts','Normal running at 6.6 m/s and Shift sprint at 8.25 m/s, retaining native 10/12 FPS eight-direction cycles','Overworld horizontal dimensions doubled to 2048 by 1152 metres, retaining physical building size, with 16464 trees, more meadow and geological dressing','M renders the actual playable overworld terrain, roads, bridges, river meshes and settlement models, with distance LOD, saved discovery fog and existing fast travel; legacy positions migrate'],
 'art':{'generator':'PixelLab','nativeSelectedFamilies':41,'runtimeFamilies':42,'packedSpritePoses':a['packedPoses'],'sourceCropWarnings':0,'newPixelLabAssets':0,'note':'V17 reuses the approved-concept-derived selected art; clouds, terrain edges and world effects are rendered procedurally.'},
 'audio':{'provider':'ElevenLabs','speechModel':'eleven_v4','recordedVoices':voices['clips'],'soundAssets':sounds['sounds'],'newNarration':23,'offline':True,'embeddedCredential':False,'transcription':transcripts},
 'validation':{'checks':reg['checks'],'revisionFeatures':revision,'tutorialAndRequests':journey,'sourceMatchesArtifact':True,'storyProgressionSteps':len(campaign['campaign']['log']),'storyBattles':len(campaign['campaign']['battles']),'restoredLights':len(campaign['campaign']['restored']),'saveLoad':campaign['persistence'],'waterJoinMaxGapMetres':max(q['maxGap']for q in water['joins']),'spriteLuminance':{k:lighting[k]for k in ['sun','shadow','cloud','night']},'overworldApproaches':macro},
 'performance':{'device':performance['device'],'nativeScenarios':performance['scenarios'],'pump':pump,'tutorial':read('onboarding-performance.json'),'combatRenderCPU':combat['cpu'],'newCombatPrograms':len(combat['newPrograms']),'atlas':atlas,'scope':'Native Chrome measurements on the tested GPU; performance varies by hardware.'}}
(root/'release.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps({'release':r['release'],'bytes':a['bytes'],'sha256':sha,'checks':len(reg['checks']),'audioAssets':voices['clips']+sounds['sounds']}))
